                 ccxt::any response = awaitValue(
                     this->privateGetGetSettlementHistoryByInstrument(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "jsonrpc": "2.0",
                 //         "result": {
                 //             "settlements": [
                 //                 {
                 //                     "type": "bankruptcy",
                 //                     "timestamp": 1696579200041,
                 //                     "funded": 10000.0,
                 //                     "session_bankrupcy": 10000.0
                 //                     "session_profit_loss":
                 //                     112951.68715857354, "session_tax": 0.15,
                 //                     "session_tax_rate": 0.0015,
                 //                     "socialized": 0.001,
                 //                 },
                 //             ],
                 //             "continuation":
                 //             "5dHzoGyD8Hs8KURoUhfgXgHpJTA5oyapoudSmNeAfEftqRbjNE6jNNUpo2oCu1khnZL9ao"
                 //         },
                 //         "usIn": 1696652052254890,
                 //         "usOut": 1696652052255733,
