                            awaitValue(this->publicGetGetBookSummaryByCurrency(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "jsonrpc": "2.0",
                        //         "result": [
                        //             {
                        //                 "mid_price": 0.4075,
                        //                 "volume_usd": 2836.83,
